exercises.starter:
function safeDivide(a, b) {
  // throw a RangeError when b is 0; otherwise return a / b
}

exercises.solution:
function safeDivide(a, b) {
  if (b === 0) throw new RangeError('cannot divide by zero')
  return a / b
}

exercises.starter:
function checkedSqrt(x) {
  // throw a RangeError when x is negative; otherwise return its square root
}

exercises.solution:
function checkedSqrt(x) {
  if (x < 0) throw new RangeError('cannot take the square root of a negative number')
  return Math.sqrt(x)
}

exercises.starter:
function getAt(arr, i) {
  // throw a RangeError when i is out of bounds; otherwise return arr[i]
}

exercises.solution:
function getAt(arr, i) {
  if (i < 0 || i >= arr.length) throw new RangeError('index out of range')
  return arr[i]
}

exercises.starter:
function parsePositive(n) {
  // throw a TypeError when n is not positive; otherwise return n
}

exercises.solution:
function parsePositive(n) {
  if (n <= 0) throw new TypeError('expected a positive number')
  return n
}

exercises.starter:
function withdraw(balance, amount) {
  // throw a RangeError for a negative amount or an overdraft; otherwise return balance - amount
}

exercises.solution:
function withdraw(balance, amount) {
  if (amount < 0 || amount > balance) throw new RangeError('invalid withdrawal')
  return balance - amount
}
